#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, TSTEPS, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "jacobi-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A and B.
 *
 * C original:
 *
 * for (i = 0; i < n; i++)
 *   for (j = 0; j < n; j++) {
 *     A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
 *     B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
 *   }
 *
 * Mapping to Halide:
 * - C index A[i][j] -> Buffer A(j, i)
 * - C index B[i][j] -> Buffer B(j, i)
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    Expr n_expr = cast<num_t>(n);

    // A[i][j] = ((i*(j+2) + 2) / n)
    init_A(j, i) = cast<num_t>(i * (j + 2) + 2) / n_expr;

    // B[i][j] = ((i*(j+3) + 3) / n)
    init_B(j, i) = cast<num_t>(i * (j + 3) + 3) / n_expr;

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size and time steps (from PolyBench headers)
    int n      = N;
    int tsteps = TSTEPS;

    // Buffers:
    // We store A and B as N x N Buffers.
    // C index A[i][j] corresponds to A_buf(j, i) in Halide.
    Halide::Buffer<num_t, 2> A_current(n, n);  // current A
    Halide::Buffer<num_t, 2> A_next(n, n);     // next A (scratch)
    Halide::Buffer<num_t, 2> B_init(n, n);     // initial B (used only for boundaries)

    // Initialize A_current and B_init
    init_array(n, A_current, B_init);

    // -------------------------------------------------------------------------
    // Build a Halide pipeline that executes a *single* Jacobi time step:
    //
    // C kernel (for one t):
    //
    // for (i = 1; i < n-1; i++)
    //   for (j = 1; j < n-1; j++)
    //     B[i][j] = 0.2 * (A[i][j] + A[i][j-1] + A[i][j+1]
    //                      + A[i+1][j] + A[i-1][j]);
    // for (i = 1; i < n-1; i++)
    //   for (j = 1; j < n-1; j++)
    //     A[i][j] = 0.2 * (B[i][j] + B[i][j-1] + B[i][j+1]
    //                      + B[i+1][j] + B[i-1][j]);
    //
    // Notes:
    // - A and B boundaries (i=0 or n-1, j=0 or n-1) are never updated.
    // - B's boundaries are used as neighbors for updating A, and they always
    //   stay equal to their initial values from init_array.
    //
    // We model one full t-step as:
    //   1) Compute an intermediate B_temp from A_prev and B_init (for boundaries).
    //   2) Compute A_next from B_temp (interior) and A_prev (boundaries).
    //
    // We then apply this single-step pipeline tsteps times from C++ using
    // double-buffering for A (A_current and A_next), as recommended for
    // loop-carried dependencies.
    // -------------------------------------------------------------------------

    // ImageParams representing the current A and the initial B.
    ImageParam A_prev_param(type_of<num_t>(), 2, "A_prev");
    ImageParam B_init_param(type_of<num_t>(), 2, "B_init");

    // Vars: j = column (x), i = row (y)
    Var j("j"), i("i");

    // Clamp A_prev at the edges so that stencil accesses
    // (j±1, i±1) are always in-bounds.
    Func A_prev_clamped =
        Halide::BoundaryConditions::repeat_edge(A_prev_param);

    // First half-step: compute B_temp from A_prev (interior) and B_init (boundaries)
    Func B_temp("B_temp");

    // Determine image extents at runtime from A_prev_param.
    Expr width  = A_prev_param.dim(0).extent();
    Expr height = A_prev_param.dim(1).extent();

    // Boundary condition: true on the outermost rows/columns.
    Expr on_boundary =
        (i == 0) || (i == height - 1) ||
        (j == 0) || (j == width  - 1);

    Expr alpha = cast<num_t>(0.2f);

    // 5-point stencil on A_prev (with clamped edges).
    Expr stencilA =
        alpha * (A_prev_clamped(j,     i    ) +
                 A_prev_clamped(j,     i - 1) +
                 A_prev_clamped(j,     i + 1) +
                 A_prev_clamped(j + 1, i    ) +
                 A_prev_clamped(j - 1, i    ));

    // For interior points: Jacobi update from A_prev.
    // For boundary points: keep B equal to its initial value (B_init),
    // matching the C code where B's boundaries are never written.
    B_temp(j, i) = select(on_boundary,
                          B_init_param(j, i),
                          stencilA);

    // Clamp B_temp at the edges for the second stencil.
    Func B_clamped =
        Halide::BoundaryConditions::repeat_edge(B_temp);

    // Second half-step: compute A_next from B_temp (interior)
    // and A_prev (boundaries, which are never updated).
    Func A_next_func("A_next");

    Expr stencilB =
        alpha * (B_clamped(j,     i    ) +
                 B_clamped(j,     i - 1) +
                 B_clamped(j,     i + 1) +
                 B_clamped(j + 1, i    ) +
                 B_clamped(j - 1, i    ));

    // For interior: Jacobi update from B_temp
    // For boundaries: keep previous A value
    A_next_func(j, i) = select(on_boundary,
                               A_prev_param(j, i),
                               stencilB);

    // A simple schedule that mirrors the original row/column traversal.
    // (We leave everything at default loop nesting, which is row-major in j,i.)
    // More aggressive scheduling (tiling, vectorization, etc.) can be added
    // later if desired.

    // Wrap the Func into a Pipeline representing a single Jacobi time step.
    Pipeline step_pipeline(A_next_func);

    // Bind the (runtime) buffers to ImageParams.
    A_prev_param.set(A_current);
    B_init_param.set(B_init);

    // JIT-compile the pipeline once.
    step_pipeline.compile_jit();

    // Run the time-stepping loop and measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // Update A_prev_param to point at the current A buffer.
        A_prev_param.set(A_current);

        // Compute A_next = Jacobi(A_current, B_init)
        step_pipeline.realize(A_next);

        // Swap current and next A buffers (double buffering).
        std::swap(A_current, A_next);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print the final A array to prevent dead-code elimination
    // and to mirror PolyBench's print_array behavior.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                std::cerr << A_current(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (like the GEMM example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
