 *   }
 *
 * C arrays are laid out as A[i][j], with i = row, j = column, and j varies fastest.
 * Following the translation rules, we map this to Halide::Buffer<num_t, 2> with
 * dimension 0 = j (x), dimension 1 = i (y), and access as A(j, i).
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    // A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
    init_A(j, i) =
        cast<num_t>(i * (j + 2) + 2) / cast<num_t>(n);

    // B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
    init_B(j, i) =
        cast<num_t>(i * (j + 3) + 3) / cast<num_t>(n);

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size and number of time steps (PolyBench-style)
    int n = N;
    int tsteps = TSTEPS;

    // Buffers:
    // A_curr: current A grid (n x n)
    // A_next: next A grid (n x n), used as scratch and then swapped with A_curr
    // B_init: initial B grid, used only for its boundary values (never updated)
    //
    // As per the mapping rule, dimension 0 is j (column), dimension 1 is i (row).
    Halide::Buffer<num_t, 2> A_curr(n, n);
    Halide::Buffer<num_t, 2> A_next(n, n);
    Halide::Buffer<num_t, 2> B_init(n, n);

    // Initialize A_curr and B_init.
    init_array(n, A_curr, B_init);

    // Halide pipeline for a single Jacobi time-step.
    //
    // Original C kernel:
    //
    // for (t = 0; t < tsteps; t++) {
    //   for (i = 1; i < n-1; i++)
    //     for (j = 1; j < n-1; j++)
    //       B[i][j] = 0.2 * (A[i][j]     + A[i][j-1] +
    //                       A[i][j+1]   + A[i+1][j] +
    //                       A[i-1][j]);
    //   for (i = 1; i < n-1; i++)
    //     for (j = 1; j < n-1; j++)
    //       A[i][j] = 0.2 * (B[i][j]     + B[i][j-1] +
    //                       B[i][j+1]   + B[i+1][j] +
    //                       B[i-1][j]);
    // }
    //
    // We express a *single* t-iteration in Halide as:
    //   1) B_tmp = Jacobi(A_curr) on the interior, with B boundaries taken from B_init
    //   2) A_new = Jacobi(B_tmp)  on the interior, with A boundaries taken from A_curr
    //
    // We then iterate this transform tsteps times from C++ using double-buffering on A.
    // B is used only for boundary values and never updated, which matches the original
    // program semantics for A (the only live-out array).
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    Var i("i"), j("j");

    // Boundary-extended version of A, to avoid out-of-bounds accesses when
    // evaluating the stencil near the edges. This satisfies Halide's bounds
    // inference requirements (see rule 7).
    Func A_padded("A_padded");
    A_padded = BoundaryConditions::repeat_edge(A_param);

    // First Jacobi sweep: compute B_tmp from A.
    Func B_tmp("B_tmp");

    // Extents of A. These are Expr, so we can use them inside Halide code.
    Expr width  = A_param.dim(0).extent(); // number of columns (j)
    Expr height = A_param.dim(1).extent(); // number of rows (i)

    // Interior condition: 1 <= i <= n-2 and 1 <= j <= n-2
    Expr interior =
        (i > 0) && (i < height - 1) &&
        (j > 0) && (j < width  - 1);

    // Jacobi weight 0.2 as a Halide Expr (SCALAR_VAL is a PolyBench macro).
    Expr alpha = Expr(SCALAR_VAL(0.2));

    // B_tmp(j, i) corresponds to B[i][j].
    B_tmp(j, i) = select(
        interior,
        alpha * (A_padded(j,     i    ) +
                 A_padded(j,     i - 1) +
                 A_padded(j,     i + 1) +
                 A_padded(j + 1, i    ) +
                 A_padded(j - 1, i    )),
        // At the boundary, keep the original B value.
        B_param(j, i));

    // Boundary-extended version of B_tmp, to safely read neighbors near the edges
    // when computing the second Jacobi sweep.
    Func B_padded("B_padded");
    B_padded = BoundaryConditions::repeat_edge(B_tmp);

    // Second Jacobi sweep: compute A_new from B_tmp.
    Func A_new("A_new");
    A_new(j, i) = select(
        interior,
        alpha * (B_padded(j,     i    ) +
                 B_padded(j,     i - 1) +
                 B_padded(j,     i + 1) +
                 B_padded(j + 1, i    ) +
                 B_padded(j - 1, i    )),
        // At the boundary, keep the original A value.
        A_param(j, i));

    // Simple schedule: rely on Halide's default (row-major traversal with j/x
    // varying fastest, i/y outer). This matches the original C loop order
    // (i outer, j inner) given our mapping of dimensions.
    //
    // We just JIT-compile A_new once and then reuse it inside the time-stepping loop.
    A_param.set(A_curr);
    B_param.set(B_init);

    A_new.compile_jit();

    // Time-stepping loop driven from the host.
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // Bind the current A buffer for this iteration.
        A_param.set(A_curr);

        // Compute A_next from A_curr (and the fixed B_init boundaries).
        A_new.realize(A_next);

        // Swap current and next A buffers for the next iteration.
        std::swap(A_curr, A_next);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the final A array to stderr (to avoid timing pollution),
    // similar in spirit to PolyBench's print_array.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
