#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common PolyBench-style definitions (e.g., DATA_TYPE, N, TSTEPS)
#include "defines.hpp"

// include benchmark-specific definitions (problem sizes, etc.)
#include "jacobi-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A and B as in the original C code.
 *
 * Original C:
 *   A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
 *   B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
 *
 * Here, Buffers are indexed as (x=j, y=i).
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {

    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    // A(j, i) corresponds to A[i][j] in the original C code.
    Expr n_expr = Expr(n);

    init_A(j, i) =
        cast<num_t>(i * (j + 2) + 2) / cast<int>(n_expr);

    init_B(j, i) =
        cast<num_t>(i * (j + 3) + 3) / cast<int>(n_expr);

    // Realize into the provided Buffers.
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate A and B as N x N Buffers.
    // Dimension 0 is x (column / j), dimension 1 is y (row / i).
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);

    // Initialize data.
    init_array(n, A, B);

    // ImageParams that will point at A and B. They represent the current
    // state of A and B at each time step.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Vars for Halide expressions.
    Var x("x"), y("y");

    // Single-step Jacobi updates:
    // We define two Funcs that compute the interior update for B from A,
    // and for A from B, over a domain (x, y) in [0, n-3] x [0, n-3].
    //
    // We then map (x, y) -> (j = x + 1, i = y + 1) to correspond to
    // the original C loop region:
    //   for (i = 1; i < n - 1; i++)
    //     for (j = 1; j < n - 1; j++)
    //
    // The stencil in the C code:
    //   B[i][j] = 0.2 * ( A[i][j] + A[i][j-1] + A[i][j+1]
    //                     + A[i+1][j] + A[i-1][j] );
    //
    // translates to (using x, y as above and A_param(j, i) == A_param(x+1,y+1)):
    //
    //   A[i][j]   -> A_param(x+1, y+1)
    //   A[i][j-1] -> A_param(x,   y+1)
    //   A[i][j+1] -> A_param(x+2, y+1)
    //   A[i+1][j] -> A_param(x+1, y+2)
    //   A[i-1][j] -> A_param(x+1, y)
    //
    // Similarly for the A update from B.
    Func step_B("step_B");
    Func step_A("step_A");

    Expr coeff = cast<num_t>(Expr(0.2));

    // Compute B's interior from A.
    step_B(x, y) = coeff *
                   (A_param(x + 1, y + 1) +
                    A_param(x,     y + 1) +
                    A_param(x + 2, y + 1) +
                    A_param(x + 1, y + 2) +
                    A_param(x + 1, y));

    // Compute A's interior from B.
    step_A(x, y) = coeff *
                   (B_param(x + 1, y + 1) +
                    B_param(x,     y + 1) +
                    B_param(x + 2, y + 1) +
                    B_param(x + 1, y + 2) +
                    B_param(x + 1, y));

    // The original C code iterates in i outer, j inner. Our loops in Halide
    // run over x, y; we don't need to reorder explicitly here, but we could
    // if desired:
    // step_B.reorder(x, y);
    // step_A.reorder(x, y);

    // Bind the ImageParams to the Buffers that hold the current state.
    A_param.set(A);
    B_param.set(B);

    // JIT-compile the per-step kernels once.
    step_B.compile_jit();
    step_A.compile_jit();

    // Temporary Buffers for the interior updates (size (n-2) x (n-2)).
    Halide::Buffer<num_t, 2> tmpB(n - 2, n - 2);
    Halide::Buffer<num_t, 2> tmpA(n - 2, n - 2);

    // Measure only the time spent in the Jacobi kernel, as in the PolyBench code.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven), following the original algorithm:
    //
    // for (t = 0; t < tsteps; t++) {
    //   // update B from A
    //   for (i = 1; i < n - 1; i++)
    //     for (j = 1; j < n - 1; j++)
    //       B[i][j] = ...
    //
    //   // update A from B
    //   for (i = 1; i < n - 1; i++)
    //     for (j = 1; j < n - 1; j++)
    //       A[i][j] = ...
    // }
    //
    // We use Halide to compute each interior update into tmpB/tmpA, then
    // copy the result back into the interior of B/A. Boundaries remain
    // unchanged, exactly as in the original C code.
    for (int t = 0; t < tsteps; ++t) {
        // 1) Compute B interior from current A into tmpB.
        //
        // step_B is defined over x, y in [0, n-3] x [0, n-3]; tmpB has that size.
        step_B.realize(tmpB);

        // 2) Copy tmpB back into the interior of B:
        //    tmpB(x, y) -> B(j = x+1, i = y+1)
        for (int i = 0; i < n - 2; ++i) {
            for (int j = 0; j < n - 2; ++j) {
                int ii = i + 1;
                int jj = j + 1;
                B(jj, ii) = tmpB(j, i);
            }
        }

        // 3) Compute A interior from current B into tmpA.
        step_A.realize(tmpA);

        // 4) Copy tmpA back into the interior of A:
        //    tmpA(x, y) -> A(j = x+1, i = y+1)
        for (int i = 0; i < n - 2; ++i) {
            for (int j = 0; j < n - 2; ++j) {
                int ii = i + 1;
                int jj = j + 1;
                A(jj, ii) = tmpA(j, i);
            }
        }

        // The ImageParams point to A and B Buffers whose contents have just
        // been updated in-place, so we do not need to call set() again here.
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print the output array (similar to PolyBench's print_array)
    // to prevent dead-code elimination and/or check correctness.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                // A(j, i) corresponds to A[i][j] in the original C code.
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing in seconds with 6 decimal places, similar to the GEMM example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
