#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "jacobi-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Array initialization using Halide.
static
void init_array(int n,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B) {
    // C layout: A[i][j], B[i][j]
    // We map to Halide layout as A(j, i), B(j, i).
    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    Expr i_f = cast<num_t>(i);
    Expr j_f = cast<num_t>(j);
    Expr n_f = cast<num_t>(n);

    // A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
    init_A(j, i) = (i_f * (j_f + 2) + 2) / n_f;

    // B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
    init_B(j, i) = (i_f * (j_f + 3) + 3) / n_f;

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;
    int tsteps = TSTEPS;

    // Full state arrays A and B (mapped as [j, i]).
    Buffer<num_t, 2> A(n, n);
    Buffer<num_t, 2> B(n, n);

    // Initialize arrays.
    init_array(n, A, B);

    // Interior buffers (for i,j in [1, n-2]).
    const int inner_n = n - 2;
    Buffer<num_t, 2> A_inner(inner_n, inner_n);
    Buffer<num_t, 2> B_inner(inner_n, inner_n);

    // Halide pipeline for one Jacobi step: A -> B (interior only).
    Var x("x"), y("y"); // local interior coordinates: x,y in [0, inner_n-1]

    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    Func step_A2B("step_A2B"), step_B2A("step_B2A");

    // Constant 0.2 in the correct scalar type.
    const Expr c = Expr((num_t)0.2);

    // Map local interior coordinates (x,y) to global indices:
    // i = y + 1, j = x + 1
    Expr jg = x + 1;
    Expr ig = y + 1;

    // B[i][j] = 0.2 * (A[i][j] + A[i][j-1] + A[i][j+1] + A[i+1][j] + A[i-1][j]);
    step_A2B(x, y) =
        c * (A_param(jg,     ig    ) +
             A_param(jg - 1, ig    ) +
             A_param(jg + 1, ig    ) +
             A_param(jg,     ig + 1) +
             A_param(jg,     ig - 1));

    // A[i][j] = 0.2 * (B[i][j] + B[i][j-1] + B[i][j+1] + B[i+1][j] + B[i-1][j]);
    step_B2A(x, y) =
        c * (B_param(jg,     ig    ) +
             B_param(jg - 1, ig    ) +
             B_param(jg + 1, ig    ) +
             B_param(jg,     ig + 1) +
             B_param(jg,     ig - 1));

    // Make traversal order explicit: i outer, j inner  (y outer, x inner).
    step_A2B.reorder(x, y);
    step_B2A.reorder(x, y);

    // Bind initial buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);

    // JIT-compile the per-step kernels.
    step_A2B.compile_jit();
    step_B2A.compile_jit();

    // Time the Jacobi iterations (kernel_jacobi_2d equivalent).
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // Step 1: A -> B (update interior of B, keep boundaries unchanged).

        // Read from current A.
        A_param.set(A);
        // Compute interior region into B_inner (size (n-2) x (n-2)).
        step_A2B.realize(B_inner);

        // Copy interior back into full B: B[i][j] for i,j in [1, n-2].
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < n - 1; j++) {
                // Mapping: B_inner(x,y) with x = j-1, y = i-1 -> B(j,i)
                B(j, i) = B_inner(j - 1, i - 1);
            }
        }

        // Step 2: B -> A (update interior of A, keep boundaries unchanged).

        // Read from current B.
        B_param.set(B);
        // Compute interior region into A_inner.
        step_B2A.realize(A_inner);

        // Copy interior back into full A: A[i][j] for i,j in [1, n-2].
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < n - 1; j++) {
                A(j, i) = A_inner(j - 1, i - 1);
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (to prevent dead-code elimination and
    // to mirror the style of the example).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // C layout A[i][j] corresponds to A(j, i)
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
